import sqlite3,re,collections
c=sqlite3.connect('file:$SP/p4/s.db?mode=ro',uri=True); c.row_factory=sqlite3.Row
need={r['need_code']:r for r in c.execute('select * from access_needs')}
idn={r['identity_code']:r for r in c.execute('select * from base_taxonomy_identity')}
anf={(r['need_code'],r['icf_code']) for r in c.execute('select * from access_need_icf')}
seen={}
bad=0
for r in c.execute('select * from identity_need_icf order by triple_id'):
    w=r['warrant']; I,N,C=r['identity_code'],r['need_code'],r['icf_code']
    m=re.search(r'Need (\S+) registry text read: "(.*?)"\. Identity (\S+) read: "(.*?)"\. Code (\S+): access_need_icf held (\S+) -> (\S+)\.(.*)$',w)
    assert m,w
    n,qn,i,qi,c1,n2,c2,rest=m.groups()
    ok = (n==N==n2 and i==I and c1==C==c2 and (N,C) in anf and rest=='' and w.startswith('As recorded when this row was written: '))
    inabs = qn in (need[N]['absorbs'] or ''); innotes = qn in (need[N]['notes'] or '')
    indn = qi in (idn[I]['display_name'] or ''); indesc= qi in (idn[I]['description'] or '')
    if not ok or not inabs or not (indn or indesc): bad+=1; print('BAD',I,N,C,ok,inabs,innotes,indn,indesc)
    body=w.split(' Code ')[0]
    seen.setdefault((I,N),set()).add(body)
    # other quotes in warrant
    for q in re.findall(r'"(.*?)"',w):
        if q not in (qn,qi): print('extra quote',I,N,C,repr(q))
print('bad',bad, 'triple ids', c.execute('select min(triple_id),max(triple_id),count(*) from identity_need_icf').fetchone()[:])
for k,v in seen.items():
    assert len(v)==1
    b=list(v)[0]
    print(k, '| qi in', 'name' if re.search(r'Identity \S+ read: "(.*?)"',b).group(1) in idn[k[0]]['display_name'] else 'desc', '\n   ',b[39:])
# axis words
for r in c.execute("select identity_code,need_code,icf_code,warrant from identity_need_icf"):
    if re.search(r'axis|axes|AX-|absorbs|confirmed|mechanism', r['warrant'], re.I): print('WORD', tuple(r)[:3])
print(c.execute("select * from sqlite_sequence where name='identity_need_icf'").fetchall())
PY
